const cache = new Map<number, QuizQuestion[]>();

export function getN3MockTest(testNumber: number): QuizQuestion[] {
  const cached = cache.get(testNumber);
  if (cached) return cached;

  const idx = Math.max(0, Math.min(8, testNumber - 2));
  const spec: SingleMockTestSpec = {
    testNumber,
    vRead: N3_VREAD_POOL.slice(idx * 8, idx * 8 + 8),
    vOrtho: N3_VORTHO_POOL.slice(idx * 6, idx * 6 + 6),
    vCtx: N3_VCTX_POOL.slice(idx * 11, idx * 11 + 11),
    vSyn: N3_VSYN_POOL.slice(idx * 5, idx * 5 + 5),
    vUse: N3_VUSE_POOL.slice(idx * 5, idx * 5 + 5),
    gSent: N3_GSENT_POOL.slice(idx * 11, idx * 11 + 11),
    gStar: N3_GSTAR_POOL.slice(idx * 4, idx * 4 + 4),
    gText: [N3_GTEXT_POOL[idx]],
    reading: N3_READING_BY_TEST[idx],
    listening: N3_LISTENING_BY_TEST[idx],
  };

  const compiled = compileMockTestSpec(JlptLevel.N3, spec, N3_VCTX_POOL);
  cache.set(testNumber, compiled);
  return compiled;
}
